write_alerts_yaml() { cat > "$1" <<'ALERTS_EOF'
# Recommended Prometheus alert rules for a self-hosted Aztec V5 sequencer/validator node.
#
# This is a portable starting point you run inside your OWN Prometheus. It has no
# dependency on any external service. Tune thresholds and `for:` durations to your
# setup before relying on them in production.
#
# Target version: V5 (v5.0.0). Metric names verified against live V5 nodes and
# the Aztec project's own dashboards/alerts. See monitoring-guide.md.
#
# The rules are grouped to match the dashboard: "Am I OK?" health, duties, costs,
# server health, and a few internal-correctness checks.
#
# Label note: these rules group by `instance` (the Prometheus scrape target). If you
# scrape multiple nodes in one Prometheus, each fires per node. If you run several node
# processes behind one target, pin OTEL_RESOURCE_ATTRIBUTES=service.instance.id per
# process and add that label to the grouping.
#
# Grafana-managed alerting is an alternative: recreate these as Grafana alert rules
# pointing at the same Prometheus datasource. The PromQL below transfers directly.

groups:
  - name: aztec-health
    rules:
      - alert: AztecNodeDown
        # The scrape target itself is unreachable.
        expr: up{job="aztec-node"} == 0
        for: 2m
        labels:
          severity: critical
        annotations:
          summary: "Node is down ({{ $labels.instance }})"
          description: "Prometheus cannot scrape the node's metrics endpoint. The node process may be down, or the metrics port is unreachable. Check the process and the metrics endpoint."

      - alert: AztecNoNewBlocks
        # No new proposed block height in 10 minutes = the node is not following the chain.
        expr: max by (instance) (increase(aztec_archiver_block_height{aztec_status="proposed"}[10m])) == 0
        for: 5m
        labels:
          severity: critical
        annotations:
          summary: "No new blocks for 10 minutes ({{ $labels.instance }})"
          description: "The node has not seen a new block in the last 10 minutes. It may be disconnected from peers or its L1 RPC. Check peers, L1 RPC reachability, and logs."

      - alert: AztecNotSynced
        # Synced L1 height not advancing for 5 minutes = the L1 RPC is stale or unreachable.
        expr: increase(aztec_archiver_l1_block_height[5m]) == 0
        for: 5m
        labels:
          severity: critical
        annotations:
          summary: "Node not keeping up with L1 ({{ $labels.instance }})"
          description: "The node's synced L1 block height has not moved in 5 minutes. The L1 execution/beacon RPC may be down, lagging, or misconfigured. Verify the L1 endpoints."

      - alert: AztecL1RpcStuck
        # The publisher's view of the L1 height stops advancing = the L1 RPC is stuck.
        # L1 produces a block roughly every 12s, so zero growth over 10m means the RPC
        # endpoint is unreachable or stalled.
        expr: increase(aztec_l1_block_height[10m]) == 0
        for: 3m
        labels:
          severity: critical
        annotations:
          summary: "L1 RPC appears stuck ({{ $labels.instance }})"
          description: "The L1 block height the node is tracking has not advanced in 10 minutes. The node's L1 RPC endpoint is likely unreachable or stalled. Check the L1 execution RPC and beacon endpoint configuration and connectivity."

  - name: aztec-duties
    rules:
      - alert: AztecFailedAttestations
        # A genuine missed attestation = the node was on the committee, was due to attest,
        # and failed for a node-side reason. We therefore:
        #  - filter aztec_is_committee_member="true" (the metric is also split on the
        #    "false" series, so summing both double-counts a single event), and
        #  - exclude aztec_error_type="block_number_already_exists" (a benign internal race
        #    of attesting to an already-known block, not a missed duty), mirroring the
        #    insufficient_txs benign-filter precedent.
        # bad_proposal failures are excluded entirely: those are the validator correctly
        # refusing to attest to an invalid block, which is correct behavior, not a fault.
        # Cumulative gauge -> use the 1h offset delta, not increase().
        expr: |
          sum by (instance) (aztec_validator_attestation_failed_node_issue_count{aztec_is_committee_member="true", aztec_error_type!="block_number_already_exists"})
          - sum by (instance) (aztec_validator_attestation_failed_node_issue_count{aztec_is_committee_member="true", aztec_error_type!="block_number_already_exists"} offset 1h) > 0
        for: 10m
        labels:
          severity: warning
        annotations:
          summary: "Failed attestations ({{ $labels.instance }})"
          description: "The node missed one or more attestations it was due to make in the last hour. Sustained failures precede an inactivity penalty. Check resources, peers, and logs; see the 'Failed attestations by reason' panel."

      - alert: AztecFailedProposals
        # Genuine proposal failures = checkpoint-proposal faults (all real) plus block-build
        # faults, excluding the benign tx-shortage error types.
        # Cumulative gauges: use the 1h offset delta, not increase().
        # Exclude aztec_error_type insufficient_txs AND insufficient_valid_txs on the
        # block-proposal term: both mark a slot skipped for having too few (valid)
        # transactions to build a block (benign on a quiet network), not a real fault.
        # checkpoint_proposal_failed error types (header_validation_failed, block_build_failed)
        # are all genuine faults and are kept.
        expr: |
          (sum by (instance) (aztec_sequencer_block_proposal_failed_count{aztec_error_type!~"insufficient_txs|insufficient_valid_txs"})
           - sum by (instance) (aztec_sequencer_block_proposal_failed_count{aztec_error_type!~"insufficient_txs|insufficient_valid_txs"} offset 1h))
          + (sum by (instance) (aztec_sequencer_checkpoint_proposal_failed_count)
             - sum by (instance) (aztec_sequencer_checkpoint_proposal_failed_count offset 1h)) > 0
        for: 10m
        labels:
          severity: warning
        annotations:
          summary: "Failed proposals ({{ $labels.instance }})"
          description: "The node had one or more genuine block or checkpoint proposal failures in the last hour (benign too-few-transaction skips are excluded). Review L1 connectivity, publisher balance, and logs; see the 'Checkpoint proposal failures by reason' panel."

      - alert: AztecFailedReexecution
        # In V5 all nodes re-execute; sustained failures mean the node cannot validate blocks.
        # Cumulative gauge: use the 1h offset delta, not increase().
        expr: |
          sum by (instance) (aztec_validator_failed_reexecution_count)
          - sum by (instance) (aztec_validator_failed_reexecution_count offset 1h) > 0
        for: 10m
        labels:
          severity: warning
        annotations:
          summary: "Failed block re-executions ({{ $labels.instance }})"
          description: "The node failed to re-execute one or more blocks in the last hour. In V5 all nodes re-execute blocks; sustained failures mean the node cannot validate the chain. Review logs and resource pressure."

  - name: aztec-costs
    rules:
      - alert: AztecPublisherBalanceLow
        # Below 0.1 ETH a single propose tx in an L1 gas spike can fail or drain the account.
        # Uses aztec_l1_balance_eth (present from node startup) rather than the
        # publisher-scope metric, which is only emitted after the node starts proposing.
        # This lets the alert fire from startup if the account is underfunded.
        expr: aztec_l1_balance_eth < 0.1
        for: 5m
        labels:
          severity: critical
        annotations:
          summary: "Publisher balance below 0.1 ETH ({{ $labels.instance }})"
          description: "The publisher account balance is below 0.1 ETH. A propose transaction during an L1 gas spike can fail or empty the account, which stops block production. Top up the publisher account."

      - alert: AztecBlobTxFailures
        # Sustained blob tx failures = proposals are not landing on L1.
        # Cumulative gauge: use the 15m offset delta, not increase().
        expr: |
          sum by (instance) (aztec_l1_publisher_blob_tx_failure)
          - sum by (instance) (aztec_l1_publisher_blob_tx_failure offset 15m) > 0
        for: 5m
        labels:
          severity: warning
        annotations:
          summary: "Blob transaction failures ({{ $labels.instance }})"
          description: "The node recorded blob transaction failures in the last 15 minutes. Proposals may not be landing on L1. Check L1 RPC, the blob-capable beacon endpoint, gas pricing, and the publisher balance."

  - name: aztec-server-health
    rules:
      - alert: AztecHighCpu
        # process_cpu_utilization is a 0..1 ratio (OTEL); compare directly, do not rate().
        expr: avg by (instance) (process_cpu_utilization{process_cpu_state="user"}) > 0.7
        for: 10m
        labels:
          severity: warning
        annotations:
          summary: "High CPU ({{ $labels.instance }})"
          description: "User CPU utilization above 0.7 (of all cores) for 10 minutes. A CPU-saturated node can miss duties. Node load is flat with attester count and scales with the number of nodes, so review per-node sizing."

      - alert: AztecHighMemory
        # system_memory_utilization carries a system_memory_state label (used/free).
        expr: avg by (instance) (system_memory_utilization{system_memory_state="used"}) > 0.9
        for: 10m
        labels:
          severity: warning
        annotations:
          summary: "High memory ({{ $labels.instance }})"
          description: "Used memory above 90% for 10 minutes. Risk of out-of-memory kills. Review host sizing and any memory growth trend."

      - alert: AztecHighProcessingLag
        # nodejs event-loop p90 in nanoseconds; 0.2s p90 means the process is saturated.
        expr: avg by (instance) (nodejs_eventloop_delay_p90_nanoseconds) / 1e6 > 200
        for: 10m
        labels:
          severity: warning
        annotations:
          summary: "High processing lag ({{ $labels.instance }})"
          description: "Event-loop p90 delay above 200ms for 10 minutes. The process is CPU-bound and may miss duties. Investigate CPU pressure and host sizing."

      - alert: AztecLowHealthyPeers
        # Too few healthy peers degrades gossip and attestation propagation.
        expr: aztec_peer_manager_healthy_peer_count_peers < 5
        for: 10m
        labels:
          severity: warning
        annotations:
          summary: "Low healthy peer count ({{ $labels.instance }})"
          description: "Fewer than 5 healthy peers for 10 minutes. Gossip and attestation propagation degrade with too few peers. Check networking, the P2P port forwarding/firewall, and the bootnode list."

  - name: aztec-correctness
    rules:
      - alert: AztecWorldStateCriticalError
        # Any world-state critical error is serious and can lead to chain divergence.
        # Cumulative gauge: use the 5m offset delta, not increase().
        expr: |
          sum by (instance) (aztec_world_state_critical_error_count)
          - sum by (instance) (aztec_world_state_critical_error_count offset 5m) > 0
        for: 0m
        labels:
          severity: critical
        annotations:
          summary: "World-state critical error ({{ $labels.instance }})"
          description: "The world-state recorded a critical error. This can lead to divergence from the canonical chain. Capture logs and review the node's state; a resync may be required."

      - alert: AztecHaSignerSlashingProtectionTriggered
        # Slashing protection blocked a sign — a duplicate/conflicting signer is likely active.
        # Cumulative gauge: use the 15m offset delta, not increase().
        expr: |
          sum by (instance) (aztec_ha_signer_slashing_protection_count)
          - sum by (instance) (aztec_ha_signer_slashing_protection_count offset 15m) > 0
        for: 0m
        labels:
          severity: critical
        annotations:
          summary: "Signer slashing protection triggered ({{ $labels.instance }})"
          description: "The signer's slashing-protection layer blocked a signature in the last 15 minutes. This usually means a second process tried to sign for the same key. Confirm only one active signer per key before continuing."
ALERTS_EOF
}
write_alertmanager_yml() { cat > "$1" <<'AM_EOF'
# Alertmanager configuration for delivering the Aztec node alerts to Telegram.
#
# This routes the alerts defined in alerts.yaml to a Telegram chat using
# Alertmanager's built-in Telegram receiver. There is no custom bot code and no extra
# service to maintain beyond Alertmanager itself. You run your own bot and your own
# Alertmanager; nothing connects to any external or Foundation-run service.
#
# alerts.yaml (loaded by Prometheus) stays the source of truth for the alert rules.
# Alertmanager only decides how those alerts are grouped, throttled, and delivered.
#
# Fill in the two placeholders below before use:
#   - bot_token: the token @BotFather gives you when you create a bot.
#   - chat_id:   the numeric ID of the chat/channel to send to (see the guide).
# See "Get alerts on Telegram" in monitoring-guide.md for the full setup.

global:
  resolve_timeout: 5m

route:
  receiver: telegram
  group_by: ["alertname"]
  group_wait: 30s
  group_interval: 5m
  repeat_interval: 4h

receivers:
  - name: telegram
    telegram_configs:
      - bot_token: "REPLACE_WITH_YOUR_BOT_TOKEN"   # from @BotFather
        # Replace with your numeric chat_id (integer, no quotes). The value below is a
        # placeholder that lets the config validate; it will not reach your chat until
        # you set your real chat_id (see the guide).
        chat_id: 123456789
        api_url: "https://api.telegram.org"
        parse_mode: HTML
        send_resolved: true
        # Concise, glanceable message: one compact block per alert in the group.
        # Iterate over .Alerts and use per-alert .Labels / .Annotations — NOT
        # .CommonLabels / .CommonAnnotations, which only carry fields identical across
        # every alert in the group, so per-alert fields (node, summary) would render blank
        # when grouped alerts differ. Emoji: critical -> red, warning -> yellow,
        # resolved -> check. Full remediation guidance lives in the guide's alert reference.
        message: |
          {{ range .Alerts }}{{ if eq .Status "resolved" }}✅ <b>RESOLVED:</b> {{ else if eq .Labels.severity "critical" }}🔴 <b>FIRING:</b> {{ else if eq .Labels.severity "warning" }}🟡 <b>FIRING:</b> {{ else }}🔴 <b>FIRING:</b> {{ end }}<b>{{ .Labels.alertname }}</b>
          <b>Severity:</b> {{ .Labels.severity }}{{ if .Labels.instance }}
          <b>Node:</b> <code>{{ .Labels.instance }}</code>{{ end }}
          {{ .Annotations.summary }}
          {{ end }}
AM_EOF
}

# ---- stack file writers ----
write_collector_config() { cat > "$1" <<'OTEL_EOF'
receivers:
  otlp:
    protocols:
      grpc:
        endpoint: 0.0.0.0:4317
      http:
        endpoint: 0.0.0.0:4318
exporters:
  prometheus:
    endpoint: 0.0.0.0:8889
processors:
  batch: {}
service:
  pipelines:
    metrics:
      receivers: [otlp]
      processors: [batch]
      exporters: [prometheus]
OTEL_EOF
}

write_monitoring_compose() { cat > "$1" <<'MC_EOF'
services:
  grafana:
    image: grafana/grafana:11.4.0
    container_name: aztec-grafana
    ports: ["3000:3000"]
    environment:
      - GF_SECURITY_ADMIN_USER=admin
      - GF_SECURITY_ADMIN_PASSWORD=admin
      - GF_USERS_ALLOW_SIGN_UP=false
    volumes:
      - grafana-data:/var/lib/grafana
      - ./grafana-provisioning:/etc/grafana/provisioning
      - ./dashboards:/var/lib/grafana/dashboards
    networks: [monitoring]
    restart: unless-stopped
  prometheus:
    image: prom/prometheus:v3.0.1
    container_name: aztec-prometheus
    ports: ["9090:9090"]
    command:
      - "--config.file=/etc/prometheus/prometheus.yml"
      - "--storage.tsdb.path=/prometheus"
      - "--storage.tsdb.retention.time=15d"
      - "--web.enable-lifecycle"
    volumes:
      - ./prometheus/prometheus.yml:/etc/prometheus/prometheus.yml:ro
      - ./prometheus/rules:/etc/prometheus/rules:ro
      - prometheus-data:/prometheus
    networks: [monitoring]
    restart: unless-stopped
  alertmanager:
    image: prom/alertmanager:latest
    container_name: aztec-alertmanager
    ports: ["9093:9093"]
    volumes:
      - ./alertmanager.yml:/etc/alertmanager/alertmanager.yml:ro
    networks: [monitoring]
    restart: unless-stopped
networks:
  monitoring:
    driver: bridge
volumes:
  grafana-data:
  prometheus-data:
MC_EOF
}

write_prometheus_yml() { # $1=path $2=nodes-string (";"-joined "endpoint|label")
  # One aztec-node job with one static_configs block per node. Each block sets a
  # target-level `instance` label (labels: { instance: <label> }); with the default
  # honor_labels=false, that pins the dashboard series while the node's generated
  # service.instance.id is preserved as exported_instance. Verified against a live V5 node.
  local _path="$1" _nodes="$2" _blocks="" _ep _lb _oldifs
  _oldifs="$IFS"; IFS=';'
  for _n in $_nodes; do
    [ -z "$_n" ] && continue
    _ep="${_n%%|*}"; _lb="${_n#*|}"
    if [ -n "$_lb" ]; then
      _blocks="${_blocks}
      - targets: [\"${_ep}\"]
        labels:
          instance: \"${_lb}\""
    else
      _blocks="${_blocks}
      - targets: [\"${_ep}\"]"
    fi
  done
  IFS="$_oldifs"
  # Heredoc is UNQUOTED so ${_blocks} interpolates; _blocks holds only quotes/newlines
  # (no $ or backticks), so it is safe to expand here.
  cat > "$_path" <<PROM_EOF
global:
  scrape_interval: 15s
  evaluation_interval: 15s
rule_files:
  - "/etc/prometheus/rules/*.yml"
  - "/etc/prometheus/rules/*.yaml"
alerting:
  alertmanagers:
    - static_configs:
        - targets: ["alertmanager:9093"]
scrape_configs:
  - job_name: "prometheus"
    static_configs:
      - targets: ["localhost:9090"]
  - job_name: "aztec-node"
    metrics_path: /metrics
    static_configs:${_blocks}
PROM_EOF
}

write_grafana_provisioning() { # $1=monitoring dir root
  mkdir -p "$1/grafana-provisioning/datasources" "$1/grafana-provisioning/dashboards" "$1/dashboards"
  cat > "$1/grafana-provisioning/datasources/prometheus.yml" <<'DS_EOF'
apiVersion: 1
datasources:
  - name: Prometheus
    uid: aztec-prometheus
    type: prometheus
    access: proxy
    url: http://prometheus:9090
    isDefault: true
    editable: true
DS_EOF
  cat > "$1/grafana-provisioning/dashboards/dashboards.yml" <<'DP_EOF'
apiVersion: 1
providers:
  - name: aztec
    orgId: 1
    folder: ""
    type: file
    disableDeletion: false
    editable: true
    options:
      path: /var/lib/grafana/dashboards
DP_EOF
  write_dashboard_json "$1/dashboards/aztec-v5-operator.json"
  sed_inplace 's/${DS_PROMETHEUS}/aztec-prometheus/g' "$1/dashboards/aztec-v5-operator.json"
}

# ---- preflight ----
have_cmd() { command -v "$1" >/dev/null 2>&1; }

require_docker() {
  if ! have_cmd docker; then
    c_red "Docker is not installed."
    if [ "$OS" = "macos" ]; then
      info "Install Docker Desktop: https://www.docker.com/products/docker-desktop/"
    else
      info "Install Docker Engine + the compose plugin for your distro, then re-run."
    fi
    return 1
  fi
  if ! docker compose version >/dev/null 2>&1; then
    c_red "The 'docker compose' plugin is not available."
    info "Install the Docker Compose v2 plugin, then re-run."
    return 1
  fi
  if ! docker info >/dev/null 2>&1; then
    c_red "Docker is installed but not running."
    [ "$OS" = "macos" ] && info "Start Docker Desktop and wait until it is ready."
    return 1
  fi
  return 0
}

# endpoint_up <host:port> — true if /metrics returns aztec_ series.
endpoint_up() {
  curl -fsS --max-time 8 "http://$1/metrics" 2>/dev/null | grep -q '^aztec_'
}

# wait_for_endpoint <host:port> <max tries> <seconds between tries> — poll endpoint_up
# until it answers; 0 on success, 1 on timeout. A keep-alive note lands every ~30s of
# sleep (every ceil(30/$3) tries) so a slow node restart does not read as a hang.
# Interval 0 would divide by zero, so it falls back to every 30 tries. No arrays (bash 3.2).
wait_for_endpoint() {
  local _ep="$1" _tries="$2" _sleep="$3" _i=0 _every
  # Malformed args must not abort under the runtime set -e (sleep '') or skip the
  # poll entirely (a test -lt error evaluates false): normalize instead.
  [ "$_tries" -gt 0 ] 2>/dev/null || _tries=1
  if [ "$_sleep" -gt 0 ] 2>/dev/null; then _every=$(( (30 + _sleep - 1) / _sleep )); else _every=30; _sleep=0; fi
  while [ "$_i" -lt "$_tries" ]; do
    endpoint_up "$_ep" && return 0
    _i=$((_i+1))
    if [ "$_i" -lt "$_tries" ]; then
      sleep "$_sleep"
      [ $((_i % _every)) -eq 0 ] && info "Still waiting — a restarting node can take several minutes to serve metrics..."
    fi
  done
  return 1
}

# ---- telegram ----
tg_extract_chat_id() { # $1=getUpdates json body -> prints chat.id or empty
  if have_cmd python3; then
    printf '%s' "$1" | python3 -c 'import json,sys
try:
    d=json.load(sys.stdin); r=d.get("result",[])
    print(r[-1]["message"]["chat"]["id"] if r else "")
except Exception:
    print("")'
  else
    printf '%s' "$1" | grep -o '"chat":{"id":[0-9-]*' | head -1 | grep -o '[0-9-]*$'
  fi
}

tg_get_me() { curl -fsS --max-time 10 "https://api.telegram.org/bot$1/getMe" 2>/dev/null | grep -q '"ok":true'; }
tg_get_updates() { curl -fsS --max-time 10 "https://api.telegram.org/bot$1/getUpdates" 2>/dev/null || printf ''; }
tg_webhook_url() { curl -fsS --max-time 10 "https://api.telegram.org/bot$1/getWebhookInfo" 2>/dev/null | grep -o '"url":"[^"]*"' | head -1 | sed 's/"url":"//; s/"$//'; }
tg_delete_webhook() { curl -fsS --max-time 10 "https://api.telegram.org/bot$1/deleteWebhook" >/dev/null 2>&1; }

tg_write_creds() { # $1=am.yml $2=token $3=chat_id
  sed_inplace "s|REPLACE_WITH_YOUR_BOT_TOKEN|$2|" "$1"
  sed_inplace "s|chat_id: 123456789|chat_id: $3|" "$1"
  chmod 600 "$1" 2>/dev/null || true
}

# Read the live values back out of alertmanager.yml. Match only the real config lines
# (leading whitespace), not the comment lines that also contain the words
# bot_token / chat_id. chat_id may be negative (group chats). Print nothing — and do
# not fail under set -e/pipefail — when the file or the line is missing.
am_read_token() { # $1=am.yml
  [ -f "$1" ] || return 0
  # sed -n/p: an unrecognized line (e.g. hand-edited unquoted token) must yield
  # nothing, never pass through as the whole line.
  grep -E '^[[:space:]]*- bot_token:' "$1" | head -1 | sed -n 's/.*"\(.*\)".*/\1/p' || true
}
am_read_chat_id() { # $1=am.yml
  [ -f "$1" ] || return 0
  grep -E '^[[:space:]]*chat_id:[[:space:]]*[0-9-]+' "$1" | head -1 | sed -n 's/.*chat_id:[[:space:]]*\([0-9-]*\).*/\1/p' || true
}

# Refresh alertmanager.yml from the embedded template without losing configured
# Telegram credentials: template changes still propagate on re-apply, but a real
# token/chat_id already in the file must survive (tg_write_creds keeps the 600 mode).
rewrite_alertmanager_preserving_creds() { # $1=am.yml
  local _amt _amc
  _amt="$(am_read_token "$1")"
  _amc="$(am_read_chat_id "$1")"
  write_alertmanager_yml "$1"
  # Re-inject only a plausible BotFather-charset token: sed-special characters
  # (|, &, \ — hand-edit only) would corrupt or abort tg_write_creds' sed.
  # chat_id is already constrained to [0-9-] by its capture group.
  case "$_amt" in ''|REPLACE_WITH_YOUR_BOT_TOKEN|*[!A-Za-z0-9:_-]*) return 0 ;; esac
  [ -n "$_amc" ] || return 0
  tg_write_creds "$1" "$_amt" "$_amc"
}

tg_send_test() { # $1=token $2=chat_id
  curl -fsS --max-time 12 -X POST "https://api.telegram.org/bot$1/sendMessage" \
    --data-urlencode "chat_id=$2" \
    --data-urlencode "text=Aztec monitoring: Telegram configured successfully." >/dev/null 2>&1
}

configure_telegram() { # $1=path to alertmanager.yml
  local _am="$1" _tok _wh _yn _chat _n _manual
  printf '\n'
  header "Set up Telegram alerts"
  info "You need a bot token and your chat id. If you do not have a bot yet:"
  info "  1. In Telegram, open @BotFather and send /newbot"
  info "  2. Follow the prompts (a display name, then a username ending in 'bot')"
  info "  3. BotFather replies with a bot TOKEN — copy it"
  info "  4. Open your new bot and press Start (or send /start) so it can message you"
  printf 'Telegram bot token (from @BotFather): '; read -r _tok
  if ! tg_get_me "$_tok"; then c_red "Token rejected by Telegram (getMe failed). Check you copied the whole token."; return 1; fi
  c_green "Token valid."
  info "In Telegram, open THIS bot and press Start (or send /start) if you have not already,"
  info "then send it any message. This is required before it can message you. Press Enter when done."
  read -r _
  _wh="$(tg_webhook_url "$_tok")"
  if [ -n "$_wh" ]; then
    c_yellow "A webhook is set ($_wh); getUpdates will be empty until it is removed."
    printf 'Delete the webhook now? [y/N]: '; read -r _yn
    case "$_yn" in y|Y) tg_delete_webhook "$_tok"; info "Webhook deleted. Send your bot another message, then press Enter."; read -r _ ;; esac
  fi
  _chat=""; _n=0
  while [ "$_n" -lt 3 ]; do
    _chat="$(tg_extract_chat_id "$(tg_get_updates "$_tok")")"
    [ -n "$_chat" ] && break
    c_yellow "No chat id yet. Make sure you pressed Start and sent a message."
    printf 'Press Enter to retry (or type the chat id manually): '; read -r _manual
    [ -n "$_manual" ] && { _chat="$_manual"; break; }
    _n=$((_n+1))
  done
  if [ -z "$_chat" ]; then c_red "Could not determine chat id."; return 1; fi
  info "Using chat id: $_chat"
  tg_write_creds "$_am" "$_tok" "$_chat"
  state_set TELEGRAM_CONFIGURED "yes"
  c_green "Telegram credentials written."
}

# ---- node-side ----

detect_node_service() { # $1=compose path -> prints service whose image looks like aztec, else first service
  if have_cmd python3; then
    python3 - "$1" <<'PY'
import sys
try:
    import yaml
except Exception:
    yaml=None
path=sys.argv[1]; name=""
if yaml:
    try:
        d=yaml.safe_load(open(path)) or {}
    except Exception:
        d={}
    svcs=d.get("services",{}) or {}
    for n,s in svcs.items():
        if "aztec" in str((s or {}).get("image","")).lower():
            name=n; break
    if not name and svcs:
        name=list(svcs.keys())[0]
print(name)
PY
  else
    # Fallback when python3 is unavailable. Service keys are indented under
    # "services:"; grab the first one. Skip blank/comment lines. Prefer a
    # service whose following lines reference an aztec image, else the first.
    awk '
      /^[[:space:]]*#/ { next }
      /^services:[[:space:]]*$/ { f=1; next }
      f && /^[^[:space:]]/ { exit }                      # left the services block
      f && /^[[:space:]]+[A-Za-z0-9_.-]+:[[:space:]]*$/ { # a service key
        line=$0; sub(/:[[:space:]]*$/,"",line); sub(/^[[:space:]]+/,"",line)
        if (first=="") first=line
        cur=line; next
      }
      f && cur!="" && tolower($0) ~ /image:.*aztec/ { print cur; done=1; exit }
      END { if (!done && first!="") print first }
    ' "$1"
  fi
}

detect_node_networks() { # $1=compose path $2=node_service -> prints network name(s) the node service is on (first is what we attach the collector to); empty = default network
  have_cmd python3 || return 0
  python3 - "$1" "$2" <<'PY'
import sys
try:
    import yaml
except Exception:
    yaml=None
path=sys.argv[1]; svc=sys.argv[2]; nets=[]
if yaml:
    try:
        d=yaml.safe_load(open(path)) or {}
    except Exception:
        d={}
    s=((d.get("services",{}) or {}).get(svc,{}) or {})
    n=s.get("networks")
    if isinstance(n,dict):
        nets=[str(k) for k in n.keys()]
    elif isinstance(n,list):
        # list entries are network names (strings); ignore non-strings defensively
        nets=[str(x) for x in n if isinstance(x,(str,int,float))]
    # if no networks key -> nets stays empty -> signal "use default"
print(" ".join(nets))
PY
}

write_node_override() { # $1=path $2=node_service $3=instance_name $4=node_network (may be empty)
  local _p="$1" _svc="$2" _inst="$3" _net="${4:-}"
  if [ -n "$_net" ]; then
    cat > "$_p" <<OV_EOF
# Added by aztec-monitoring.sh — exposes node metrics via an OpenTelemetry Collector.
# Docker Compose auto-merges this file with your base compose. Remove this file to undo.
services:
  ${_svc}:
    environment:
      - OTEL_EXPORTER_OTLP_METRICS_ENDPOINT=http://otel-collector:4318/v1/metrics
      - OTEL_SERVICE_NAME=aztec-sequencer
      - OTEL_RESOURCE_ATTRIBUTES=service.instance.id=${_inst}
    networks:
      - ${_net}
  otel-collector:
    image: otel/opentelemetry-collector-contrib:latest
    container_name: aztec-otel-collector
    command: ["--config=/etc/otel/config.yaml"]
    volumes:
      - ./otel-collector.yaml:/etc/otel/config.yaml:ro
    ports:
      - "8889:8889"
    networks:
      - ${_net}
    restart: unless-stopped
networks:
  ${_net}:
    external: true
OV_EOF
  else
    cat > "$_p" <<OV_EOF
# Added by aztec-monitoring.sh — exposes node metrics via an OpenTelemetry Collector.
# Docker Compose auto-merges this file with your base compose. Remove this file to undo.
services:
  ${_svc}:
    environment:
      - OTEL_EXPORTER_OTLP_METRICS_ENDPOINT=http://otel-collector:4318/v1/metrics
      - OTEL_SERVICE_NAME=aztec-sequencer
      - OTEL_RESOURCE_ATTRIBUTES=service.instance.id=${_inst}
  otel-collector:
    image: otel/opentelemetry-collector-contrib:latest
    container_name: aztec-otel-collector
    command: ["--config=/etc/otel/config.yaml"]
    volumes:
      - ./otel-collector.yaml:/etc/otel/config.yaml:ro
    ports:
      - "8889:8889"
    restart: unless-stopped
OV_EOF
  fi
}

setup_node() {
  [ "$OS" = "macos" ] && { c_yellow "Option 1 is for your Linux Aztec node, not this machine."; return 1; }
  require_docker || return 1
  state_load
  local _compose="${NODE_COMPOSE:-}" _dir _svc _net _default_inst _inst _ovr _yn
  if [ -z "$_compose" ]; then
    for c in ./docker-compose.yml ./compose.yml "$HOME/aztec/docker-compose.yml" "$HOME/.aztec/docker-compose.yml"; do
      [ -f "$c" ] && { _compose="$c"; break; }
    done
  fi
  if [ -z "$_compose" ] || [ ! -f "$_compose" ]; then
    printf 'Path to your Aztec node docker-compose.yml (absolute path, e.g. /root/aztec-sequencer/docker-compose.yml): '; read -r _compose
    case "$_compose" in
      "~/"*) _compose="$HOME/${_compose#\~/}" ;;
      "~") _compose="$HOME" ;;
    esac
  fi
  [ -f "$_compose" ] || { c_red "No compose file at: $_compose"; return 1; }
  _dir="$(cd "$(dirname "$_compose")" && pwd)"
  _svc="$(detect_node_service "$_compose")"
  [ -n "$_svc" ] || { c_red "Could not find a node service in the compose file."; return 1; }
  info "Node service: $_svc"
  _net="$(detect_node_networks "$_compose" "$_svc" | awk '{print $1}')"
  [ -n "$_net" ] && info "Node network: $_net (collector will join it)"
  # The node's service.instance.id is set below for future-proofing, but current node
  # versions override it with a generated value, so it does not name the dashboard series.
  # The dashboard instance label is pinned on the monitoring side (option 2). No prompt here.
  _inst="${NODE_INSTANCE:-$(hostname 2>/dev/null || echo aztec-node)}"
  _inst="$(printf '%s' "$_inst" | tr -d '\n\r' | tr -c 'A-Za-z0-9._-' '_')"
  write_collector_config "$_dir/otel-collector.yaml"
  _ovr="$_dir/docker-compose.override.yml"
  if [ -f "$_ovr" ]; then
    c_yellow "An override file already exists: $_ovr"
    cp "$_ovr" "$_ovr.bak.$(date +%s 2>/dev/null || echo backup).$$"
    info "Backed it up. This script will overwrite it with the metrics override."
    printf 'Continue? [y/N]: '; read -r _yn; case "$_yn" in y|Y) : ;; *) return 1;; esac
  fi
  write_node_override "$_ovr" "$_svc" "$_inst" "$_net"
  info "----- planned changes (docker-compose.override.yml) -----"
  cat "$_ovr"
  info "---------------------------------------------------------"
  printf 'Apply and restart the node with these changes? [y/N]: '; read -r _yn
  case "$_yn" in y|Y) : ;; *) c_yellow "Aborted; override written but not applied. Remove $_ovr to discard."; return 1;; esac
  if ( cd "$_dir" && docker compose up -d ); then
    state_set NODE_COMPOSE "$_compose"; state_set NODE_INSTANCE "$_inst"
  else
    c_red "docker compose up -d failed. Your override is at $_ovr."
    info "Review 'docker compose -f \"$_compose\" config', check that port 8889 is free, then re-run or remove the override to revert."
    return 1
  fi
  info "Waiting for metrics on localhost:8889 (a node restart can take several minutes)..."
  if wait_for_endpoint "localhost:8889" 60 5; then
    c_green "Metrics are live on localhost:8889/metrics."
    info "Allow your monitoring machine to reach this host on :8889 (private/firewalled, not public)."
    info "The dashboard's node label is set on the monitoring machine (option 2), not here."
  else
    c_yellow "No metrics on :8889 yet — the setup is applied and nothing needs re-running; the node is likely still starting."
    info "Re-check later with: curl -s localhost:8889/metrics | grep -c '^aztec_'  (or menu option 4)."
    info "Only if it stays empty well after the node finishes syncing, check 'docker compose logs otel-collector'."
  fi
}

# ---- monitoring-side ----
# Not "$HOME/aztec-monitoring": that is where a 'git clone' of this repo lands, and the
# stack must not write runtime files (including a creds-filled alertmanager.yml) into a
# git checkout.
MON_DIR_DEFAULT="$HOME/aztec-monitoring-stack"

setup_monitoring() {
  require_docker || return 1
  state_load
  local _dir="${MON_DIR:-$MON_DIR_DEFAULT}" _nodes _in _lb _yn _tok _cid _idx _n_count _choice _first_run=0
  # A git checkout of this repo must not become the stack directory: option 2 writes
  # runtime files there, including alertmanager.yml with real credentials, which a
  # 'git pull' or checkout would then fight with. Installs recorded in state keep
  # their directory (moving would orphan a running stack) but get a warning.
  if [ -e "$_dir/.git" ] || [ -f "$_dir/aztec-monitoring.sh" ]; then
    if [ -n "${MON_DIR:-}" ]; then
      c_yellow "Warning: your monitoring stack directory ($_dir) looks like a git checkout of this repo. Consider migrating (uninstall option 5, re-run option 2) so 'git pull' never conflicts with your live credentials."
    else
      c_yellow "$_dir looks like a git checkout of this repo; using $HOME/aztec-monitoring-stack for the stack instead."
      _dir="$HOME/aztec-monitoring-stack"
    fi
  fi
  mkdir -p "$_dir/prometheus/rules"
  # Working node list, seeded from state (with legacy single-node migration).
  _nodes="$(nodes_load_string)"
  # First run = no monitoring stack recorded yet.
  [ -z "${MON_DIR:-}" ] && _first_run=1

  # If there are no nodes yet, require at least the first one before showing the menu.
  if [ -z "$_nodes" ]; then
    header "Add your first Aztec node"
    while [ -z "$_nodes" ]; do
      printf 'Aztec node metrics endpoint (host:port, e.g. <node-ip>:8889): '
      read -r _in || { c_yellow "Cancelled; no changes applied."; return 0; }
      case "$_in" in
        *:*) : ;;
        *) c_yellow "That does not look like host:port (needs a ':'). Try again."; continue ;;
      esac
      case "$_in" in *[\;\|]*) c_yellow "Endpoint may not contain ';' or '|'. Try again."; continue ;; esac
      [ -n "$_in" ] || continue
      printf 'Pin a stable dashboard instance label for this node (optional, e.g. sequencer-1): '; read -r _lb
      [ -n "$_lb" ] && _lb="$(printf '%s' "$_lb" | tr -d '\n\r' | tr -c 'A-Za-z0-9._-' '_')"
      _nodes="$(node_list_append "$_nodes" "$_in" "$_lb")"
    done
  fi

  # Node-management loop.
  while :; do
    printf '\n'
    header "Nodes to monitor"
    node_list_print "$_nodes"
    printf '\n'
    info "  a) Add a node   r) Remove a node   d) Done (apply)   c) Cancel"
    printf 'Choose [a/r/d/c]: '
    read -r _choice || { c_yellow "Cancelled; no changes applied."; return 0; }
    case "$_choice" in
      a|A)
        printf 'Aztec node metrics endpoint (host:port, e.g. <node-ip>:8889): '; read -r _in
        case "$_in" in
          *:*) : ;;
          *) c_yellow "That does not look like host:port (needs a ':'). Not added."; continue ;;
        esac
        case "$_in" in *[\;\|]*) c_yellow "Endpoint may not contain ';' or '|'. Not added."; continue ;; esac
        [ -n "$_in" ] || { c_yellow "Empty endpoint; not added."; continue; }
        if node_list_has_endpoint "$_nodes" "$_in"; then
          c_yellow "This endpoint is already monitored."
          printf 'Add anyway? [y/N]: '; read -r _yn
          case "$_yn" in y|Y) : ;; *) c_yellow "Not added."; continue ;; esac
        fi
        printf 'Pin a stable dashboard instance label (optional, e.g. sequencer-2): '; read -r _lb
        [ -n "$_lb" ] && _lb="$(printf '%s' "$_lb" | tr -d '\n\r' | tr -c 'A-Za-z0-9._-' '_')"
        if node_list_has_label "$_nodes" "$_lb"; then
          c_yellow "Label '$_lb' is already used; two targets with the same instance label will collide on the dashboard."
          printf 'Add anyway? [y/N]: '; read -r _yn
          case "$_yn" in y|Y) : ;; *) c_yellow "Not added."; continue ;; esac
        fi
        _nodes="$(node_list_append "$_nodes" "$_in" "$_lb")"
        c_green "Added."
        ;;
      r|R)
        _n_count="$(node_list_count "$_nodes")"
        if [ "$_n_count" -le 0 ]; then c_yellow "No nodes to remove."; continue; fi
        printf 'Remove which? [1-%s] (or blank to cancel): ' "$_n_count"; read -r _idx
        case "$_idx" in
          ''|*[!0-9]*) c_yellow "Nothing removed."; continue ;;
        esac
        if [ "$_idx" -lt 1 ] || [ "$_idx" -gt "$_n_count" ]; then c_yellow "Out of range; nothing removed."; continue; fi
        _nodes="$(node_list_remove "$_nodes" "$_idx")"
        c_green "Removed."
        ;;
      d|D)
        if [ -z "$_nodes" ]; then c_yellow "You have no nodes; add at least one or cancel."; continue; fi
        break
        ;;
      c|C)
        c_yellow "Cancelled; no changes applied."
        return 0
        ;;
      *) c_yellow "Please choose a, r, d, or c." ;;
    esac
  done

  # Apply.
  write_monitoring_compose "$_dir/docker-compose.yml"
  write_prometheus_yml "$_dir/prometheus/prometheus.yml" "$_nodes"
  write_alerts_yaml "$_dir/prometheus/rules/alerts.yaml"
  rewrite_alertmanager_preserving_creds "$_dir/alertmanager.yml"
  write_grafana_provisioning "$_dir"
  state_set MON_DIR "$_dir"; state_set MON_NODES "$_nodes"
  # Legacy single-node keys are now fully represented by MON_NODES; drop them.
  state_unset NODE_ENDPOINT; state_unset MON_INSTANCE_NAME
  # Offer Telegram on first setup, or later if it is not yet configured.
  if [ "$_first_run" -eq 1 ] || [ "${TELEGRAM_CONFIGURED:-no}" != "yes" ]; then
    printf 'Set up Telegram alerts now? [Y/n]: '; read -r _yn
    case "$_yn" in
      n|N) c_yellow "Skipping Telegram; you can run menu option 3 later." ;;
      *) configure_telegram "$_dir/alertmanager.yml" || c_yellow "Telegram not configured; continuing." ;;
    esac
  fi
  if ( cd "$_dir" && docker compose up -d ); then
    c_green "Stack is up."
    # `up -d` recreates prometheus only if its compose definition changed, not when the
    # mounted prometheus.yml changed. Reload the running config so an edited node list is
    # picked up without a restart; fall back to a forced recreate if the reload signal fails.
    ( cd "$_dir" && docker compose exec -T prometheus kill -HUP 1 ) >/dev/null 2>&1 \
      || ( cd "$_dir" && docker compose up -d --force-recreate prometheus ) >/dev/null 2>&1 || true
    _myip="$(primary_ip)"
    printf '\n'
    header "Open the dashboard"
    info "  - On this machine:        http://localhost:3000"
    if [ -n "$_myip" ]; then
      info "  - From another computer:  http://$_myip:3000   (this machine's IP)"
    fi
    info "  Login: admin / admin  (change the password after first login)."
    info "  Prometheus: http://localhost:9090${_myip:+  (or http://$_myip:9090)}"
    info "  If this is a remote/cloud server, use its public IP, or tunnel with:"
    info "    ssh -L 3000:localhost:3000 <user>@<this-server>   then open http://localhost:3000"
  else
    c_red "docker compose up -d failed in $_dir. Check the compose output above for the cause:"
    info "  - image pull / 'failed to resolve reference' errors: this machine cannot reach docker.io — check network, VPN, and Docker's DNS (try 'docker pull alpine'), then re-run."
    info "  - port conflicts: ports 3000/9090/9093 must be free."
    info "  Nothing is lost — your settings are kept; re-run option 2 and apply once the cause is fixed."
    return 1
  fi
  info "Verifying the node scrape targets (this can take up to ~40s for the first scrape)..."
  _n_total="$(node_list_count "$_nodes")"
  _tgt_ok=0; _up=0; _i=0
  while [ "$_i" -lt 12 ]; do
    _up="$(curl -fsS --max-time 8 "http://localhost:9090/api/v1/targets" 2>/dev/null \
            | grep -o '"health":"up"' | grep -c . || true)"
    # localhost:9090 (prometheus self-scrape) is one of the "up" targets; require the
    # aztec-node targets to be up too, i.e. more ups than just prometheus itself.
    if [ "$_up" -ge $((_n_total + 1)) ]; then _tgt_ok=1; break; fi
    _i=$((_i+1)); sleep 4
  done
  if [ "$_tgt_ok" -eq 1 ]; then
    c_green "Prometheus targets are up ($_n_total node target(s) reporting)."
  else
    c_yellow "Not all node targets are up yet ($_up of $((_n_total + 1)) up, incl. prometheus). Check each node is reachable and firewall-open on :8889 (open http://localhost:9090/targets to inspect)."
  fi
  if [ "${TELEGRAM_CONFIGURED:-no}" = "yes" ]; then
    info "Firing a Telegram test alert..."
    _tok="$(am_read_token "$_dir/alertmanager.yml")"
    _cid="$(am_read_chat_id "$_dir/alertmanager.yml")"
    if [ -n "$_tok" ] && [ -n "$_cid" ] && [ "$_tok" != "REPLACE_WITH_YOUR_BOT_TOKEN" ]; then
      # retry a few times — a transient network blip should not read as "failed".
      _tg_ok=0; _j=0
      while [ "$_j" -lt 3 ]; do
        if tg_send_test "$_tok" "$_cid"; then _tg_ok=1; break; fi
        _j=$((_j+1)); sleep 3
      done
      if [ "$_tg_ok" -eq 1 ]; then
        c_green "Test message sent to Telegram."
      else
        c_yellow "Could not send a Telegram test message. The token and chat id are saved; check this machine can reach api.telegram.org, then re-test with menu option 3."
      fi
    fi
  fi
}

# ---- status / uninstall ----
show_status() {
  state_load
  header "Status"
  info "OS: $OS"
  info "State file: $STATE_FILE"
  [ -f "$STATE_FILE" ] && sed 's/^/  /' "$STATE_FILE"
  _nodes="$(nodes_load_string)"
  if [ -n "$_nodes" ]; then
    info "Monitored nodes:"
    node_list_print "$_nodes"
  fi
  if have_cmd docker && docker info >/dev/null 2>&1; then
    info "Containers:"
    docker ps --format '  {{.Names}}  {{.Status}}' | grep -E 'aztec-(grafana|prometheus|alertmanager|otel)' || info "  (none running)"
    if curl -fsS --max-time 5 http://localhost:9090/api/v1/targets >/dev/null 2>&1; then
      info "Prometheus target health:"
      curl -fsS http://localhost:9090/api/v1/targets 2>/dev/null | grep -o '"health":"[a-z]*"' | sort | uniq -c | sed 's/^/  /' || info "  (no targets reporting yet)"
    fi
  fi
  info "Telegram configured: ${TELEGRAM_CONFIGURED:-no}"
}

uninstall() {
  state_load
  local _u _d _yn
  printf 'Uninstall which? [1] node-side override  [2] monitoring stack  [c] cancel: '; read -r _u
  case "$_u" in
    1)
      if [ -n "${NODE_COMPOSE:-}" ]; then
        _d="$(dirname "$NODE_COMPOSE")"
        rm -f "$_d/docker-compose.override.yml" "$_d/otel-collector.yaml"
        # --remove-orphans drops the otel-collector service that is no longer in the
        # (now override-less) config; plain 'up -d' would leave it running.
        ( cd "$_d" && docker compose up -d --remove-orphans ) || c_yellow "Removed override, but 'docker compose up -d' reported an issue."
        # Belt-and-suspenders: remove the collector container directly in case it was not
        # tracked as a project orphan.
        docker rm -f aztec-otel-collector >/dev/null 2>&1 || true
        c_green "Removed node override + collector; your base compose was untouched."
        state_unset NODE_COMPOSE; state_unset NODE_INSTANCE
        state_prune_if_empty
      else
        c_yellow "No node install recorded in state."
      fi ;;
    2)
      if [ -n "${MON_DIR:-}" ] && [ -d "$MON_DIR" ]; then
        ( cd "$MON_DIR" && docker compose down ) || c_yellow "'docker compose down' reported an issue."
        printf 'Also delete %s? [y/N]: ' "$MON_DIR"; read -r _yn
        case "$_yn" in y|Y) rm -rf "$MON_DIR"; c_green "Deleted $MON_DIR." ;; *) c_green "Stack stopped; files kept." ;; esac
        state_unset MON_DIR; state_unset MON_NODES; state_unset NODE_ENDPOINT; state_unset MON_INSTANCE_NAME; state_unset TELEGRAM_CONFIGURED
        state_prune_if_empty
      else
        c_yellow "No monitoring install recorded in state."
      fi ;;
    *) info "Cancelled." ;;
  esac
}

# ---- lib-only guard: when sourced as a library, stop here (do not run main) ----
if [ "${AZTEC_MON_LIB_ONLY:-0}" = "1" ]; then
  return 0 2>/dev/null || true
fi

set -euo pipefail

main() {
  state_load
  while :; do
    printf '\n'
    printf '%s\n' "${_C_BOLD}${_C_CYAN}Aztec V5 Monitoring Setup${_C_RESET}"
    printf '%s\n' "${_C_DIM}─────────────────────────${_C_RESET}"
    printf '  %s1%s  Set up node metrics        %srun on your Aztec node (Linux)%s\n' "${_C_BOLD}" "${_C_RESET}" "${_C_DIM}" "${_C_RESET}"
    printf '  %s2%s  Set up monitoring stack    %srun on your monitoring machine%s\n' "${_C_BOLD}" "${_C_RESET}" "${_C_DIM}" "${_C_RESET}"
    printf '  %s3%s  Configure / test Telegram  %spush alerts to your phone%s\n' "${_C_BOLD}" "${_C_RESET}" "${_C_DIM}" "${_C_RESET}"
    printf '  %s4%s  Show status                %swhat is installed / running%s\n' "${_C_BOLD}" "${_C_RESET}" "${_C_DIM}" "${_C_RESET}"
    printf '  %s5%s  Uninstall%s\n' "${_C_BOLD}" "${_C_RESET}" ""
    printf '  %s6%s  Exit%s\n' "${_C_BOLD}" "${_C_RESET}" ""
    printf 'Choose: '
    read -r _c || exit 0
    case "$_c" in
      1) setup_node || true ;;
      2) setup_monitoring || true ;;
      3)
        state_load
        _amp="${MON_DIR:-$MON_DIR_DEFAULT}/alertmanager.yml"
        if [ -f "$_amp" ]; then
          # With saved credentials, "test" comes first — no re-pasting the token.
          _t3_tok="$(am_read_token "$_amp")"; _t3_cid="$(am_read_chat_id "$_amp")"
          _t3_reconf=1
          if [ -n "$_t3_tok" ] && [ "$_t3_tok" != "REPLACE_WITH_YOUR_BOT_TOKEN" ] && [ -n "$_t3_cid" ]; then
            info "Sending a test message with the saved Telegram settings..."
            if tg_send_test "$_t3_tok" "$_t3_cid"; then
              c_green "Test message sent to Telegram."
            else
              c_yellow "Could not send with the saved settings. Check this machine can reach api.telegram.org, or reconfigure below."
            fi
            printf 'Reconfigure Telegram credentials? [y/N]: '; read -r _yn
            case "$_yn" in y|Y) : ;; *) _t3_reconf=0 ;; esac
          fi
          if [ "$_t3_reconf" -eq 1 ]; then
            if configure_telegram "$_amp"; then
              ( cd "$(dirname "$_amp")" && docker compose up -d --force-recreate alertmanager >/dev/null 2>&1 ) || true
              c_green "Alertmanager reloaded with new Telegram settings."
              _t3_tok="$(am_read_token "$_amp")"; _t3_cid="$(am_read_chat_id "$_amp")"
              if [ -n "$_t3_tok" ] && [ "$_t3_tok" != "REPLACE_WITH_YOUR_BOT_TOKEN" ] && [ -n "$_t3_cid" ] && tg_send_test "$_t3_tok" "$_t3_cid"; then
                c_green "Test message sent to Telegram."
              fi
            fi
          fi
        else
          c_yellow "Set up the monitoring stack (option 2) first."
        fi || true ;;
      4) show_status || true ;;
      5) uninstall || true ;;
      6|q|Q) exit 0 ;;
      *) c_yellow "Pick 1-6." ;;
    esac
  done
}
main "$@"
